 "content": "def transform(grid):
    """Stamp a 3x3 field of color 1 around each embedded color-2 marker."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]
    centers = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            # A marker belongs to a filled panel when it is surrounded by
            # at least two orthogonal color-3 cells. Isolated exterior 2s
            # are distractors and do not launch a stamp.
            neighbors = ((r-1,c), (r+1,c), (r,c-1), (r,c+1))
            if sum(0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 3
                   for rr, cc in neighbors) >= 2:
                centers.append((r, c))
    for r, c in centers:
